import {TableIcon} from '@primer/octicons-react'
import {ActionList, Button} from '@primer/react'
import {Banner} from '@primer/react/experimental'
import {useCallback, useEffect, useState} from 'react'

import {type ParsedTableDataType, useDatabaseContext} from '../../../contexts/DatabaseContext'
import {ReadOnlyKey, useReadOnly} from '../../../hooks/use-read-only'
import {Section} from '../Section'
import styles from './DataPanel.module.css'
import {DataObjectDialog} from './DataPanel/DataObjectDialog'

export function DataPanel() {
  const readOnly = useReadOnly(ReadOnlyKey.DEFAULT)

  const {isFetchingData, didErrorFetchingData, fetchAllData} = useDatabaseContext()

  const [selectedTable, setSelectedTable] = useState<ParsedTableDataType | undefined>(undefined)
  const {currentData} = useDatabaseContext()

  const handleObjectDialogClose = useCallback(async () => {
    setSelectedTable(undefined)
  }, [])

  const handleRetryFetchData = useCallback(async () => {
    await fetchAllData()
  }, [fetchAllData])

  // listen to the currentData and update the currentTable if it matches
  useEffect(() => {
    if (currentData && selectedTable) {
      const matchingTable = currentData.find(table => table.table === selectedTable.table)
      if (matchingTable) {
        setSelectedTable(matchingTable)
      } else {
        setSelectedTable(undefined)
      }
    }
  }, [currentData, selectedTable])

  return (
    <>
      <div className="mt-3">
        <Section title="Tables" showTitle={false} readOnly={readOnly} loading={isFetchingData}>
          <Section.Items>
            <p className="fgColor-muted text-small">
              Add data storage by asking in the Iterate panel. View and edit the associated tables and data here.
            </p>
          </Section.Items>
          {didErrorFetchingData && (
            <Banner
              title="We couldn't load your data"
              description="Please try again. If the problem persists, try again later."
              variant="critical"
              primaryAction={
                <Button loading={isFetchingData} onClick={handleRetryFetchData}>
                  Retry
                </Button>
              }
            />
          )}
          {currentData && (
            <ActionList className={styles.actionList}>
              {currentData.map(table => (
                <ActionList.Item
                  className={styles.listItem}
                  key={table.table}
                  onSelect={() => {
                    setSelectedTable(table)
                  }}
                >
                  <ActionList.LeadingVisual>
                    <TableIcon />
                  </ActionList.LeadingVisual>
                  {table.table}
                  <ActionList.Description variant="block">{getItemDescription(table)}</ActionList.Description>
                </ActionList.Item>
              ))}
            </ActionList>
          )}
        </Section>
      </div>

      {selectedTable && (
        <DataObjectDialog onClose={handleObjectDialogClose} currentTable={selectedTable} readOnly={readOnly} />
      )}
    </>
  )
}

function getItemDescription(table: ParsedTableDataType): string {
  switch (table.data.type) {
    case 'table':
      return `${table.data.data.length} rows • ${table.data.allKeys.join(', ')}`
    case 'array':
      return `Array with ${table.data.data.length} items`
    case 'object':
      return table.data.data === null ? 'null' : `Object with ${Object.keys(table.data.data).length} keys`
    default:
      return String(table.data.data)
  }
}

try{ DataPanel.displayName ||= 'DataPanel' } catch {}